SELECT m.* FROM material m
m.is_deleted = 0 AND m.status = 1
AND m.material_type = #{materialType}
AND m.course_id = #{courseId}
AND (m.material_name LIKE CONCAT('%', #{keyword}, '%') OR m.keyword LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY m.download_count ORDER BY m.create_time ORDER BY m.file_size ORDER BY m.create_time
ASC DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM material m

    m.is_deleted = 0 AND m.status = 1

        AND m.material_type = #{materialType}


        AND m.course_id = #{courseId}


        AND (m.material_name LIKE CONCAT('%', #{keyword}, '%')
             OR m.keyword LIKE CONCAT('%', #{keyword}, '%'))
